
tape( 'the function truncates a string to the specified length (mode=code_point)', function test( t ) {
	var expected;
	var actual;
	var opts;
	var str;
	var len;

	opts = {
		'mode': 'code_point'
	};

	str = '🐺 Wolf Brothers 🐺';
	len = 7;
	expected = '🐺 ... 🐺';
	actual = truncateMiddle( str, len, opts );
	t.strictEqual( actual, expected, 'returns expected value' );

	str = '🐺 Wolf Brothers 🐺';
	len = 8;
	expected = '🐺 Wo>s 🐺';
	actual = truncateMiddle( str, len, '>', opts );
	t.strictEqual( actual, expected, 'returns expected value' );

	t.end();
});

tape( 'the function truncates a string to the specified length (mode=code_unit)', function test( t ) {
	var expected;
	var actual;
	var opts;
	var str;
	var len;

	opts = {
		'mode': 'code_unit'
	};

	str = '🐺 Wolf Brothers 🐺';
	len = 7;
	expected = '\ud83d\udc3a ... \ud83d\udc3a';
	actual = truncateMiddle( str, len, opts );
	t.strictEqual( actual, expected, 'returns expected value' );

	str = 'beep boop';
	len = 5;
	expected = 'be|op';
	actual = truncateMiddle( str, len, '|', opts );
	t.strictEqual( actual, expected, 'returns expected value' );

	t.end();
});
